#!/usr/bin/env python3
# THE DEUTERONOMY WALK sitting 1 — THE OPENING SPEECH (2026-09-15): THE CLAIMS of Deuteronomy 1:1-3:29, SIX manifests for the six draft units,
# read off this sitting's ledger, every claim LABELED (logic/MIDDOT.md's codes; World/step9/CLAIM_LABELS.md), a machine check where the ink
# allows — every he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the word's CONSONANTS: the check is the word's LONGEST PIECE
# WHOLE (never a prefix fragment; the floor four code points). Claim IDs DV01A-, DV01B-, DV02A-, DV02B-, DV03A-, DV03B- (Devarim, the chapter,
# the unit's letter). Written once (no file may exist; the ID prefixes checked absent from every existing manifest and unit). Every source
# cite is checked against the ledger's CITE INDEX before a byte is written. Sitting 15's form.
import json, os, re, sqlite3, glob, subprocess
ROOT = _ROOT
DATE = '2026-09-15'
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth, (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    assert len(piece) >= 4, (book, ch, v, word, he.split('/'))
    return idx, piece
def hc(ref, word, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
def onk(c, lo, hi): return '; '.join(f'Onkelos Deut {c}:{v}' for v in range(lo, hi + 1))
def sif(*rows): return '; '.join(f'Sifrei Devarim {r}' for r in rows)
def sifp(p, n): return sif(*[f'{p}:{r}' for r in range(1, n + 1)])
led = open(f'{ROOT}/logic/oral_triage/deu_01_03_devarim_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
CI = set(re.findall(r'^(Onkelos Deut \d+:\d+|Sifrei Devarim \d+:\d+)$', led, re.M))
assert len(CI) == 259, len(CI)

